using Demo.Telemetry;
class TelemetryReader {
    static VehicleTelemetry Sample() => new VehicleTelemetry { VehicleId = "car-1", SpeedMps = 12.5f };
    static object Observe(VehicleTelemetry entity) => new { vehicle_id = entity.VehicleId, speed_mps = entity.SpeedMps };
    static bool Speeding(VehicleTelemetry entity) => entity.SpeedMps > 30.0f;
}

from generated.telemetry_pb2 import VehicleTelemetry

def sample():
    return VehicleTelemetry(vehicle_id="car-1", speed_mps=12.5)
def observe(entity):
    return {"vehicle_id": entity.vehicle_id, "speed_mps": entity.speed_mps}
def speeding(entity):
    return entity.speed_mps > 30.0

import { VehicleTelemetry } from "./generated/telemetry";
export const sample = () => VehicleTelemetry.create({ vehicleId: "car-1", speedMps: 12.5 });
export const observe = (entity: VehicleTelemetry) => ({ vehicle_id: entity.vehicleId, speed_mps: entity.speedMps });
export const speeding = (entity: VehicleTelemetry) => entity.speedMps > 30.0;
